import{_ as a,a as e,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"从零开始学游泳","description":"以水中适应、呼吸、漂浮和动作配合组织游泳入门导读，强调从阅读到有指导的练习。","frontmatter":{"title":"从零开始学游泳","description":"以水中适应、呼吸、漂浮和动作配合组织游泳入门导读，强调从阅读到有指导的练习。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 个人成长、心理学与健康生活 · 运动与健康","summary":"以水中适应、呼吸、漂浮和动作配合组织游泳入门导读，强调从阅读到有指导的练习。","status":"active","related":[{"title":"肌肉力量训练 彩色图谱","link":"/life/personal/books/growth/strength-training","kind":"书籍导读","scope":"general","audience":"general"},{"title":"精准拉伸","link":"/life/personal/books/growth/stretching","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"精准拉伸","link":"/life/personal/books/growth/stretching"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"精准拉伸","link":"/life/personal/books/growth/stretching"},"next":false},"headers":[],"relativePath":"life/personal/books/growth/swimming.md","filePath":"life/personal/books/growth/swimming.md"}'),n={name:"life/personal/books/growth/swimming.md"};function i(l,t,s,d,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="从零开始学游泳" tabindex="-1">从零开始学游泳 <a class="header-anchor" href="#从零开始学游泳" aria-label="Permalink to &quot;从零开始学游泳&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：个人成长、心理学与健康生活 → 运动与健康。</strong> 游泳入门书帮助初学者理解水中呼吸、身体平衡和推进动作。它适合在上课前建立概念、练习后回顾动作，但书面理解需要在合适场所的实际练习中逐步转化。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《从零开始学游泳》：可核全题为《从零开始学游泳：仰泳、蛙泳、蝶泳、自由泳技巧完全图解》，作者为堀内善辉。</strong> <a href="https://detail.youzan.com/show/goods?alias=2of6fcye90x4h&amp;from_source=gbox_seo" target="_blank" rel="noopener noreferrer">人民邮电出版社官方店铺</a>列出2015年第1版、ISBN 9787115401861，并介绍作者的竞技游泳与青少年教学经历。相关经验来自游泳训练和教学，分步照片是知识材料，不能直接证明读者已具备水中能力。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合想建立泳姿概念的初学者，以及上课后需要回顾分解动作的学习者。没有水中经验者可先准备课堂问题；书面理解不构成独立下水、救生或开放水域能力的证明。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>已核到堀内善辉著、人民邮电出版社2015年第1版、ISBN 9787115401861；用户ISBN仍需对照。出版目录按仰泳、蛙泳、蝶泳、自由泳展开；下表保留本站入门主题导读，不冒充原书目录，也不等同于课程教学顺序。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>主要内容</th><th>阅读后的练习目标</th></tr></thead><tbody><tr><td>水中适应</td><td>熟悉入水、站立、移动及与水接触时的感受。</td><td>在教练或合格指导下建立稳定的基本动作。</td></tr><tr><td>呼吸</td><td>认识水中呼气与抬头、转头吸气的配合。</td><td>避免一直憋气后仓促换气，先练习节奏。</td></tr><tr><td>漂浮与平衡</td><td>理解身体位置、放松程度和浮力的关系。</td><td>在浅水教学环境中练习漂浮与恢复站立。</td></tr><tr><td>腿部与手臂</td><td>观察动作方向、节奏和对身体前进的影响。</td><td>分解练习后逐渐组合，不只追求用力。</td></tr><tr><td>泳姿配合</td><td>将呼吸、划臂、打腿和身体位置连接起来。</td><td>根据实际所学泳姿，逐步减少动作之间的停顿。</td></tr><tr><td>持续游进与复盘</td><td>从短距离动作稳定发展到连续游进。</td><td>先保持呼吸与动作可控，再增加练习距离。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 初学游泳的困难常常来自对水的紧张和多个动作同时发生。分解动作能降低复杂度，但最终仍要回到身体平衡、呼吸与推进的整体配合。一本图文清楚的书，可以帮助理解教练的反馈，也能让练习后的回顾更加具体。</p><p>阅读不会自动带来水中安全能力。入门练习应在有救生保障的场所进行，并接受适当指导；游泳池里的动作熟练也不能直接等同于开放水域的应对能力。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 能描述一个泳姿，与能在水里稳定完成它，是需要分别检查的两件事。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 按正在学习的一种泳姿，列身体位置、手腿配合与呼吸时机三个观察问题，带到有指导的课程中核对。课后只记教练确认的一项差异，回查图示，避免记了很多术语却不知道对应什么动作。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>连续照片便于看清分解过程，但难呈现节奏、阻力与紧张时的表现；同时学习四泳姿也容易超出初学者负荷。<strong>推荐语：</strong> 适合用作游泳课前预习和课后查阅书，一次读当前泳姿，学习效果由实际教学反馈检验。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://search.worldcat.org/search?q=%E4%BB%8E%E9%9B%B6%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%B8%B8%E6%B3%B3" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：用于核对作者、版本与目录，当前未确认原书章目。</li><li>实物目录应与实际学习的泳姿及教练课程对照，避免混用不同动作体系的提示。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const b=a(n,[["render",i]]);export{g as __pageData,b as default};
